// ─────────────────────────── HELPERS ───────────────────────────
const norm = s => String(s ?? "").normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().trim();

// formata em reais SEM depender de Intl (seguro no sandbox da ferramenta)
function brl(v){
  const [i, d] = Number(v).toFixed(2).split(".");
  return "R$ " + i.replace(/\B(?=(\d{3})+(?!\d))/g, ".") + "," + d;
}
function round2(v){ return Math.round((v + Number.EPSILON) * 100) / 100; }
function numCm(v){
  if (typeof v === "number") return v;
  const s = String(v).toLowerCase().replace(",", ".");
  const n = parseFloat(s.replace(/[^0-9.]/g, ""));
  if (isNaN(n)) return NaN;
  if (/m\s*$/.test(s) && !/[cm]m\s*$/.test(s)) return n * 100; // sufixo "m" isolado = metros: "1,5m" -> 150
  return n;
}

// ─────────────────────────── CÁLCULO DE PLACAS ───────────────────────────
function acharMaterial(txt){
  const t = norm(txt);
  if (t.includes("pvc")) return "PVC";
  if (t.includes("acm")) return "ACM";
  if (t.includes("acril")) {
    const mm  = (t.match(/(\d+)\s*mm/) || [])[1];
    const esp = ["2","3","4","5","10"].includes(mm) ? mm : "2"; // sem espessura => 2mm
    return "Acrilico " + esp + "mm";
  }
  if (t.includes("lona")) return "Lona";
  if (t.includes("aco") || t.includes("metal")) return "Aco";
  return null;
}
function acharTipo(txt){
  const t = norm(txt);
  if (t.includes("reflet")) return "Refletiva";
  if (t.includes("foto") || t.includes("luminescente")) return "Fotoluminescente";
  if (t.includes("uv") || t.includes("impress")) return "Impressao UV";
  return "Normal";
}
function faixaExpoente(maior, banda){
  let b = 4;
  for (const [lim, exp] of FAIXAS) if (maior >= lim) b = exp;
  if (banda === "estreita" && b < -1) b = -1; // acrílicos param na faixa -1
  return b;
}
function valorM2(refM2, maior, banda){
  if (banda === "fixa") return refM2; // Lona: m² fixo
  const b = faixaExpoente(maior, banda);
  return b >= 0 ? refM2 * Math.pow(1 + TAXA, b) : refM2 * Math.pow(1 - TAXA, -b);
}

// opts.exigirEspessuraPvc: true no documento de orçamento (a espessura precisa constar)
function calcularPrecoPlaca({ material, tipo, largura, altura, quantidade = 1, placaEndereco = false }, opts){
  opts = opts || {};
  const mat = acharMaterial(material);
  if (!mat) return { ok:false, erro:`material não reconhecido ("${material}"). Use PVC, ACM, Aço, Acrílico (2/3/4/5/10 mm) ou Lona.` };
  const cfg   = MATERIAIS[mat];
  const tp    = acharTipo(tipo);
  const refM2 = cfg.tipos[tp];

  // PVC: se a espessura veio no texto, ela entra no nome; no documento é obrigatória
  let nomeMat = cfg.nome, descMat = cfg.desc;
  if (mat === "PVC") {
    const espPvc = (norm(material).match(/(\d+)\s*mm/) || [])[1];
    if (espPvc) { nomeMat = `PVC ${espPvc}mm`; descMat = `chapa de PVC ${espPvc}mm`; }
    else if (opts.exigirEspessuraPvc) return { ok:false, erro:'informe a espessura do PVC no material (ex.: "PVC 2mm").' };
  }

  const L = numCm(largura), A = numCm(altura);
  if (!(L > 0) || !(A > 0)) return { ok:false, erro:"faltam as medidas. Informe largura e altura em centímetros." };

  const qtd    = Math.max(1, Math.round(Number(quantidade) || 1));
  const maior  = Math.max(L, A), menor = Math.min(L, A);
  const m2     = valorM2(refM2, maior, cfg.banda);
  const areaM2 = (L / 100) * (A / 100);
  const calc   = Math.round(areaM2 * m2);
  const minimo = placaEndereco ? cfg.minPlacaEnd : cfg.min;
  const unit   = Math.max(calc, minimo);
  const total  = unit * qtd;
  const cabe   = menor <= Math.min(cfg.largMax, cfg.altMax) && maior <= Math.max(cfg.largMax, cfg.altMax);

  return {
    ok:true, material:nomeMat, materialDesc:descMat, tipo:TIPO_NOME[tp],
    largura_cm:L, altura_cm:A, quantidade:qtd,
    faixa: cfg.banda === "fixa" ? 0 : faixaExpoente(maior, cfg.banda),
    preco_m2_aplicado:+m2.toFixed(2),
    areaM2, unitario:unit, total,
    valor_unitario:brl(unit), valor_total:brl(total),
    dentro_do_limite:cabe,
  };
}

// ─────────────────────────── CÁLCULO DE ITENS DE CATÁLOGO ───────────────────────────
function faixaQuantidade(qtd){
  for (let i = 0; i < FAIXAS_QTD.length; i++) {
    if (qtd >= FAIXAS_QTD[i].min && qtd <= FAIXAS_QTD[i].max) return { idx:i, rotulo:FAIXAS_QTD[i].rotulo };
  }
  return null; // acima de 100
}

// Resolve o texto do cliente/agente para um item do catálogo.
// Retorna { slug } | { ambiguo:[slugs] } | { corte:true } | { usarPlaca:true } | null
// A ORDEM das regras importa (validada por testes): sinais explícitos de placa de
// trânsito primeiro; depois famílias de itens; depois materiais de placa personalizada
// (redirect); por último heurísticas de forma (redonda/triangular) e "aço" genérico.
function resolverItem(texto){
  const t = norm(texto).replace(/[_\-]/g, " ");

  // slug exato (com _ ou espaço)
  const slugTry = norm(texto).replace(/\s+/g, "_").replace(/-/g, "_");
  if (CATALOGO[slugTry]) return { slug: slugTry };

  const has = (...ws) => ws.some(w => t.includes(w));

  // corte especial: não cotável. "\bcorte\b" não captura "recorte"; e "adesivo/vinil
  // de corte" é o adesivo de recorte do catálogo, não corte especial.
  if (!has("adesivo", "vinil") && /(\bcorte\b|\blaser\b|\brouter\b|\bcnc\b)/.test(t)) return { corte:true };

  // placas de trânsito CONTRAN — sinais EXPLÍCITOS (antes de tudo, para "placa de
  // pare com suporte" não virar suporte)
  if (/\bpare\b/.test(t) || /\br\s*[- ]?1\b/.test(t)) return { slug:"placa_transito_r1" };
  if (/\br\s*[- ]?2\b/.test(t)) return { slug:"placa_transito_r2" };
  if (/\br\s*[- ]?([3-9]|[1-3][0-9]|40)\b/.test(t)) return { slug:"placa_transito_r3_a_r40" };
  if (has("50x50", "50 x 50") && has("aco", "aço")) return { slug:"placa_aco_50x50_refletiva" };

  // famílias de itens do catálogo
  if (has("abracadeira", "abraçadeira")) {
    if (t.includes("40")) return { slug:"abracadeira_40cm" };
    if (t.includes("50")) return { slug:"abracadeira_50cm" };
    return { ambiguo:["abracadeira_40cm", "abracadeira_50cm"] };
  }
  if (has("bate roda", "bate-roda", "baterroda", "baterodas", "bate rodas")) return { slug:"bate_rodas" };
  if (has("balizador")) return { slug:"cone_balizador_118cm" };
  if (has("cone")) {
    if (has("118")) return { slug:"cone_balizador_118cm" };
    if (has("flexivel", "flexível", "nbr")) return { slug:"cone_flexivel_75cm" };
    if (has("rigido", "rígido")) return { slug:"cone_rigido_75cm" };
    return { ambiguo:["cone_flexivel_75cm", "cone_rigido_75cm", "cone_balizador_118cm"] };
  }
  if (has("corrente")) {
    if (has("grande")) return { slug:"corrente_pedestal_grande" };
    if (has("pequen")) return { slug:"corrente_pedestal_pequena" };
    return { ambiguo:["corrente_pedestal_grande", "corrente_pedestal_pequena"] };
  }
  if (has("pedestal")) return { slug:"pedestal_zebrado" };
  if (has("tachao", "tachoes")) {
    if (/sem\s+instal/.test(t)) return { slug:"tachao_sem_instalacao" };
    if (/com\s+instal|instalad/.test(t)) return { slug:"tachao_com_instalacao" };
    return { ambiguo:["tachao_com_instalacao", "tachao_sem_instalacao"] };
  }
  if (/\btach(a|as|inha|inhas)\b/.test(t)) {
    if (/sem\s+instal/.test(t)) return { slug:"tachinha_sem_instalacao" };
    if (/com\s+instal|instalad/.test(t)) return { slug:"tachinha_com_instalacao" };
    return { ambiguo:["tachinha_com_instalacao", "tachinha_sem_instalacao"] };
  }
  if (has("cavalete")) return { slug:"cavalete_dupla_face" };
  if (has("fita")) {
    if (has("zebrad")) return { slug:"fita_zebrada" };
    if (has("amarel", "vermelh")) return { slug:"fita_amarela_vermelha" };
    return { ambiguo:["fita_zebrada", "fita_amarela_vermelha"] };
  }
  if (has("adesivo", "vinil")) {
    if (has("recort") || /\bcorte\b/.test(t)) return { slug:"adesivo_recorte" };
    if (has("impress", "digital")) return { slug:"adesivo_impresso" };
    return { ambiguo:["adesivo_recorte", "adesivo_impresso"] };
  }

  // material de placa personalizada → redireciona ANTES de suporte/poste e das formas
  // ("placa de pvc para poste" e "placa redonda de acrílico" são placas personalizadas)
  if (/(\bpvc\b|\bacm\b|acril|\blona\b|fotolumin)/.test(t)) return { usarPlaca:true };

  if (has("suporte", "poste", "mourao", "mourão")) {
    if (has("madeira")) return { slug:"suporte_madeira_3m" };
    if (has("aco", "aço", "tubo", "metal", "ferro", "galvaniz")) return { slug:"suporte_tubo_aco_3m" };
    return { ambiguo:["suporte_madeira_3m", "suporte_tubo_aco_3m"] };
  }

  // heurísticas de forma, só sem material definido (placa CONTRAN por descrição)
  if (has("octogonal")) return { slug:"placa_transito_r1" };
  if (has("preferencia", "preferência", "triangular")) return { slug:"placa_transito_r2" };
  if (has("redonda", "proibido estacionar", "regulament")) return { slug:"placa_transito_r3_a_r40" };

  // "aço" genérico (sem forma CONTRAN) → placa personalizada
  if (/\baco\b/.test(t)) return { usarPlaca:true };

  return null;
}

function calcularPrecoItem({ produto, quantidade = 1, largura, altura }){
  const res = resolverItem(produto);

  if (res && res.corte) return {
    ok:false, transferir:true,
    erro:"corte especial (laser/router) não é cotado pelo atendimento. Diga ao cliente que um especialista vai preparar esse orçamento e chame a ferramenta 'transferir' (motivo: corte especial).",
  };
  if (res && res.usarPlaca) return {
    ok:false, usar_placa:true,
    erro:"isso é placa personalizada sob medida — use a ferramenta 'calcular_preco_placa' (material, tipo, largura, altura, quantidade), não esta.",
  };
  if (!res) return {
    ok:false, nao_encontrado:true, transferir:true,
    erro:`produto fora da tabela ("${produto}"). Diga ao cliente, com naturalidade, que esse item quem orça é um especialista da equipe e chame a ferramenta 'transferir' (motivo: produto fora da tabela). NUNCA diga que não trabalhamos com o item.`,
  };
  if (res.ambiguo) return {
    ok:false, ambiguo:true,
    opcoes: res.ambiguo.map(s => ({ produto:s, nome:CATALOGO[s].nome })),
    erro:"produto ambíguo. Pergunte ao cliente qual destas opções ele deseja: " + res.ambiguo.map(s => CATALOGO[s].nome).join(" | "),
  };

  const item = CATALOGO[res.slug];
  const qtd  = Math.round(Number(quantidade) || 1);
  if (!(qtd >= 1)) return { ok:false, erro:"informe a quantidade (número inteiro a partir de 1)." };

  const fx = faixaQuantidade(qtd);
  if (!fx) return {
    ok:false, transferir:true,
    erro:`quantidade de ${qtd} unidades passa do limite da tabela (100). Diga ao cliente que volumes assim têm condição especial e chame a ferramenta 'transferir' (motivo: quantidade acima de 100).`,
  };

  const precoFaixa = item.precos[fx.idx];
  let unit, extras = {};

  if (item.porM2) {
    const L = numCm(largura), A = numCm(altura);
    if (!(L > 0) || !(A > 0)) return { ok:false, erro:`para ${item.nome.toLowerCase()} preciso das medidas. Informe largura e altura em centímetros.` };
    const areaM2 = (L / 100) * (A / 100);
    unit = Math.max(round2(areaM2 * precoFaixa), MINIMO_ADESIVO);
    extras = { largura_cm:L, altura_cm:A, area_m2:+areaM2.toFixed(4), preco_m2:precoFaixa };
  } else {
    unit = precoFaixa;
  }

  const total = round2(unit * qtd);
  return {
    ok:true, produto:res.slug, nome:item.nome, quantidade:qtd, faixa:fx.rotulo,
    unitario:unit, total, valor_unitario:brl(unit), valor_total:brl(total), ...extras,
  };
}

// Linhas de características do item para o documento de orçamento
function specsItem(slug, calc){
  const item = CATALOGO[slug];
  const linhas = item.specs.slice();
  if (item.porM2 && calc && calc.largura_cm) {
    linhas.push(`Dimensões: ${String(calc.altura_cm).replace(".", ",")} x ${String(calc.largura_cm).replace(".", ",")} cm (A x L)`);
    if (calc.area_m2) linhas.push(`Área: ${String(+calc.area_m2.toFixed(3)).replace(".", ",")} m² por peça`);
  }
  return linhas;
}

