// ─────────────────────────────────────────────────────────────
// Lista de números conhecidos
// ─────────────────────────────────────────────────────────────
// Exemplo: substitua pelos números que você quer tratar de forma especial (equipe, fornecedores, parceiros)
const LISTA = [
  { nome: 'FORNECEDOR EXEMPLO', numero: '+55 11 99999-0001' },
  { nome: 'PARCEIRO EXEMPLO',   numero: '+55 11 99999-0002' },
  { nome: null,                 numero: '+55 11 99999-0003' },
];

const CC = '55';
const onlyDigits = (v) => String(v ?? '').replace(/\D/g, '');

// Gera as variantes de um número, em ordem: sem 9º dígito -> com 9º dígito
function gerarVariantes(raw) {
  let d = onlyDigits(raw).replace(/^0+/, '');

  // tira o DDI se vier (55 + DDD + 8|9 dígitos = 12 ou 13)
  if (d.length > 11 && d.startsWith(CC)) d = d.slice(CC.length);

  const out = [];
  const add = (v) => { if (v && !out.includes(v)) out.push(v); };

  if (d.length < 10) { add(d); return out; }

  const ddd = d.slice(0, 2);
  const assinante = d.slice(2);

  if (assinante.length === 9 && assinante.startsWith('9')) {
    add(CC + ddd + assinante.slice(1)); // 12 dígitos (sem 9º)
    add(CC + ddd + assinante);          // 13 dígitos (com 9º)
  } else if (assinante.length === 8) {
    add(CC + ddd + assinante);          // 12 dígitos
    // só celular ganha 9º dígito; fixo (2,3,4,5) não
    if (/^[6-9]/.test(assinante)) add(CC + ddd + '9' + assinante);
  } else {
    add(CC + ddd + assinante);
  }

  return out;
}

// Índice: cada variante da lista aponta para a entrada original
const INDEX = new Map();
for (const entrada of LISTA) {
  for (const v of gerarVariantes(entrada.numero)) {
    if (!INDEX.has(v)) INDEX.set(v, entrada);
  }
}

// ─────────────────────────────────────────────────────────────
// Execução
// ─────────────────────────────────────────────────────────────
const globalItems = $('global_var').all();

return $input.all().map((item, i) => {
  const src = globalItems[i] ?? globalItems[0];
  const telefone = src?.json?.telefone_limpo ?? null;

  const variantes = gerarVariantes(telefone);

  let encontrado = null;
  let varianteQueBateu = null;

  for (const v of variantes) {              // testa sem 9º, depois com 9º
    if (INDEX.has(v)) {
      encontrado = INDEX.get(v);
      varianteQueBateu = v;
      break;
    }
  }

  return {
    json: {
      ...item.json,
      telefone_limpo: telefone,
      variantes_testadas: variantes,
      na_lista: Boolean(encontrado),        // <- true / false
      match_nome: encontrado?.nome ?? null,
      match_numero: encontrado?.numero ?? null,
      match_variante: varianteQueBateu,
    },
  };
});

// Decide o que fazer com uma mensagem fromMe (enviada pela empresa).
const g = $('global_var').first().json;

// wasSentByApi = true  -> foi a propria IA enviando pela API. Ignora (senao ela se pausaria sozinha).
if (g.wasSentByApi === true) {
  return [{ json: { acao: 'ignorar' } }];
}

// Humano digitou no WhatsApp. Frase de reativacao explicita?
const msg = (g.mensagem || '')
  .toString()
  .toLowerCase()
  .replace(/[.!?\s]+$/, '')
  .replace(/\s+/g, ' ')
  .trim();

const frasesReativacao = ['até mais', 'atendimento finalizado'];
if (frasesReativacao.includes(msg)) {
  return [{ json: { acao: 'reativar' } }];
}

// Qualquer outra mensagem de humano -> pausa a IA nesta conversa.
return [{ json: { acao: 'pausar' } }];

// Cliente em HUMANO voltou a mandar mensagem. Reativa a IA se a pausa ja passou de 3h.
const row = $('findClient').all()[0]?.json || {};
const pausadoEm = row.pausado_em;

let reativar = true; // sem pausado_em (registros presos antigos) -> reativa no primeiro retorno
if (pausadoEm) {
  const ms = Date.now() - new Date(pausadoEm).getTime();
  reativar = Number.isFinite(ms) ? (ms >= 3 * 60 * 60 * 1000) : true;
}

return [{ json: { reativar_3h: reativar, remoteJid: row.remoteJid ?? null } }];
